parameters.jsCode:
const incident = $json;

const isEscalation =
  incident.notification_type === "manager_escalation";

if (
  !incident.task_id ||
  !incident.lease_token ||
  !incident.incident_id ||
  !["initial_alert", "manager_escalation"].includes(
    incident.notification_type
  )
) {
  throw new Error("Invalid claimed incident notification");
}

// Configure these using authorized operational destinations.
// During testing, both may point to your own test inbox.
const RESPONDER_EMAIL = "";
const MANAGER_EMAIL = "";

const recipient = isEscalation
  ? MANAGER_EMAIL
  : RESPONDER_EMAIL;

if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(recipient)) {
  throw new Error(
    `Missing authorized ${isEscalation ? "manager" : "responder"} recipient`
  );
}

const subject = isEscalation
  ? `[MANAGER ESCALATION] ${incident.title ?? "Incident"}`
  : `[INCIDENT ALERT] ${incident.title ?? "Incident"}`;

const message = [
  isEscalation
    ? "An incident has exceeded its escalation deadline without acknowledgment."
    : "A high-risk incident requires investigation.",
  "",
  `Incident: ${incident.title ?? "Unknown"}`,
  `Priority: ${incident.priority ?? "Unknown"}`,
  `Incident ID: ${incident.incident_id}`,
  `Organization ID: ${incident.organization_id}`,
  `Acknowledgment deadline: ${incident.acknowledgment_due_at ?? "Unknown"}`,
  `Escalation deadline: ${incident.escalation_due_at ?? "Unknown"}`,
  "",
  "Please open TraceOps and take the appropriate action.",
  "Do not approve refunds or execute financial actions by replying."
].join("\n");

return {
  json: {
    ...incident,
    recipient,
    subject,
    message
  }
};

